/**
 * Recruitment card artwork extracted from the generated Arena Kingdom unit-card image.
 * The source artwork is kept as a transparent WebP asset instead of being redrawn as SVG.
 *
 * Red Kingdom uses the same source asset with a CSS hue shift, preserving the exact artwork,
 * highlights and silhouette while adapting the team colour.
 */
export type ShopUnitType = 'soldier' | 'archer' | 'knight';

export const UNIT_SHOP_ASSETS: Record<ShopUnitType, string> = {
  soldier: 'data:image/webp;base64,',
  archer: 'data:image/webp;base64,',
  knight: 'data:image/webp;base64,'
};
